import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Retrospective — weights-as-programs (falsified)","description":"","frontmatter":{"title":"Retrospective — weights-as-programs (falsified)","type":"retro","date":"2026-09-25T00:00:00.000Z"},"headers":[],"relativePath":"graphopt/project/retros/weight-as-programs.md","filePath":"vendored/graphopt/project/retros/weight-as-programs.md"}`),a={name:`graphopt/project/retros/weight-as-programs.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="retrospective-—-weights-as-programs-falsified" tabindex="-1">Retrospective — weights-as-programs (falsified) <a class="header-anchor" href="#retrospective-—-weights-as-programs-falsified" aria-label="Permalink to “Retrospective — weights-as-programs (falsified)”">​</a></h1><p>The hypothesis: trained weights hide compressible structure; treat the weight file as a program and let catopt search over it.</p><h2 id="what-was-tried" tabindex="-1">What was tried <a class="header-anchor" href="#what-was-tried" aria-label="Permalink to “What was tried”">​</a></h2><ul><li>Phase 0/0b — intra-matrix algebra probes (Toeplitz displacement, H-matrix, sparse, monarch ALS, INR coordinate manifold, Kronecker).</li><li>Phase 5 — real perplexity on stories15M/TinyStories: structural compression destroys quality at every rank; only plain int8 RTN preserves ppl (4×, 5.16 vs 5.03 baseline).</li><li>Relational probes — cross-layer bitwise duplicates, shared subspaces, Procrustes alignment: zero on stories15M + stories110M.</li><li>Symmetry probes — equivariance (WG=GW), polynomial identities, learned displacement operators: all full-rank/generic.</li></ul><h2 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to “Verdict”">​</a></h2><p>Trained checkpoint weights are entropy-dense — no emergent exact structure exists. Approximate structure (Kronecker, low-rank) exists but norm bounds don&#39;t predict task quality, so it isn&#39;t usable for compression either.</p><p>What survived and shipped in catopt: exact architectural structure (tying, GQA replication, dead params), the certified-approximation toolkit as an optional module (activation paths / verification — where norm bounds ARE the contract), and the lesson that read like a negative but is the actual finding: <strong>the weight file is not a program worth rewriting; the computation graph is.</strong></p><p>See <code>adrs/0001-weight-space-structure-falsified.md</code> for the decision record; the report&#39;s full measurements were migrated to <code>docs/results_curated.md</code> §7 when it was retired.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};